-- Loads the generated V2 dataset (snowflake/v2/out/*.csv) into a new schema.
-- The original ANALYTICS schema is left untouched for rollback.
-- Run: snow sql -f snowflake/v2/load.sql -c PJOSE_AWS3_ADMIN  (from the repo root)
USE ROLE ACCOUNTADMIN;
USE WAREHOUSE DC_WAREHOUSE;
CREATE SCHEMA IF NOT EXISTS CABLEBAHAMAS_DEMO.ANALYTICS_V2
  COMMENT = 'Cable Bahamas agent data generated from the web demo baseline (as of 2026-10-31). Synthetic.';
USE SCHEMA CABLEBAHAMAS_DEMO.ANALYTICS_V2;
CREATE FILE FORMAT IF NOT EXISTS CSV_HEADER TYPE = CSV PARSE_HEADER = TRUE FIELD_OPTIONALLY_ENCLOSED_BY = '"' EMPTY_FIELD_AS_NULL = TRUE;
CREATE FILE FORMAT IF NOT EXISTS CSV_SKIP TYPE = CSV SKIP_HEADER = 1 FIELD_OPTIONALLY_ENCLOSED_BY = '"' EMPTY_FIELD_AS_NULL = TRUE;
CREATE STAGE IF NOT EXISTS LOAD_STAGE;
PUT 'file://snowflake/v2/out/*.csv' @LOAD_STAGE AUTO_COMPRESS = TRUE OVERWRITE = TRUE;
CREATE OR REPLACE TABLE PRODUCTS USING TEMPLATE (SELECT ARRAY_AGG(OBJECT_CONSTRUCT(*)) WITHIN GROUP (ORDER BY ORDER_ID) FROM TABLE(INFER_SCHEMA(LOCATION => '@LOAD_STAGE/PRODUCTS.csv.gz', FILE_FORMAT => 'CSV_HEADER')));
COPY INTO PRODUCTS FROM @LOAD_STAGE/PRODUCTS.csv.gz FILE_FORMAT = (FORMAT_NAME = 'CSV_SKIP') ON_ERROR = ABORT_STATEMENT;
CREATE OR REPLACE TABLE CUSTOMERS USING TEMPLATE (SELECT ARRAY_AGG(OBJECT_CONSTRUCT(*)) WITHIN GROUP (ORDER BY ORDER_ID) FROM TABLE(INFER_SCHEMA(LOCATION => '@LOAD_STAGE/CUSTOMERS.csv.gz', FILE_FORMAT => 'CSV_HEADER')));
COPY INTO CUSTOMERS FROM @LOAD_STAGE/CUSTOMERS.csv.gz FILE_FORMAT = (FORMAT_NAME = 'CSV_SKIP') ON_ERROR = ABORT_STATEMENT;
