COPY INTO CUSTOMER_MOVEMENTS FROM @LOAD_STAGE/CUSTOMER_MOVEMENTS.csv.gz FILE_FORMAT = (FORMAT_NAME = 'CSV_SKIP') ON_ERROR = ABORT_STATEMENT;
