-- Audited proposed actions written by the agent's PROPOSE_ACTION tool and decided in the app.
CREATE TABLE IF NOT EXISTS ACTION_LOG (
  ACTION_ID VARCHAR DEFAULT UUID_STRING(), TITLE VARCHAR, DETAIL VARCHAR, CATEGORY VARCHAR,
  STATUS VARCHAR DEFAULT 'PENDING_APPROVAL', PROPOSED_BY VARCHAR DEFAULT CURRENT_USER(), PROPOSED_AT TIMESTAMP_LTZ DEFAULT CURRENT_TIMESTAMP(),
  DECIDED_BY VARCHAR, DECIDED_AT TIMESTAMP_LTZ);
